package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.UserDAO; import com.example.ecommerce.model.User; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(r,p);}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=new UserDAO().login(req.getParameter("email"),req.getParameter("password"));if(u==null){req.setAttribute("error","E-posta veya şifre hatalı.");doGet(req,resp);return;}req.getSession().setAttribute("user",u);resp.sendRedirect(req.getContextPath()+"/home");}catch(Exception e){throw new ServletException(e);}}}
